const svcs=[];for(let i=1;i<=24;i++)svcs.push('svc-'+String(i).padStart(2,'0'));
const strip=t=>t.split('\n').map(l=>l.replace(/^\s*\d+\t/,''));
let out=[];
for(const s of svcs){
 const dk=strip(tools.read({path:'services/'+s+'/Dockerfile'}));
 let froms=[],lastUser=null;
 for(let i=0;i<dk.length;i++){ const l=dk[i].trim(); let m=l.match(/^FROM\s+(.*)$/i); if(m){ let rest=m[1].trim(); if(rest.startsWith('--')){ rest=rest.split(/\s+/).slice(1).join(' ');} let img=rest.split(/\s+/)[0]; let mm=img.match(/@sha256:([0-9a-f]*)$/); froms.push(img+' [hexlen='+(mm?mm[1].length:'none')+']'); } let u=l.match(/^USER\s+(.*)$/i); if(u){ lastUser=u[1].trim(); } }
 const rd=strip(tools.read({path:'services/'+s+'/README.md'})); const rb=[]; for(let i=0;i<rd.length;i++){ if(rd[i].indexOf('Runbook')>=0) rb.push((i+1)+':['+rd[i]+']'); }
 out.push(s+' FROM '+froms.join(' ; ')+' || LASTUSER='+lastUser+' || RUNBOOK '+(rb.length?rb.join(' '):'NONE'));
}
print(out.join('\n'));

