```js
function analyze(src){
  // returns {code: masked source (comments and string contents replaced), strings:[{val,line}]}
  let i=0,n=src.length,masked='',strings=[],line=1;
  const q=s=>s==='"'||s==="'";
  while(i<n){
    const c=src[i];
    if(c==='\n'){masked+=c;line++;i++;continue;}
    if(c==='#'){ let j=src.indexOf('\n',i); if(j<0)j=n; masked+=' '.repeat(j-i); i=j; continue; }
    if(q(c)){
      // check triple
      let triple = src.startsWith(c+c+c,i);
      let start=i; let delim = triple?c+c+c:c;
      let j=i+delim.length; let val='';
      while(j<n){
        if(src[j]==='\\'){ val+=src.slice(j,j+2); j+=2; continue; }
        if(triple){ if(src.startsWith(delim,j)){ j+=3; break; } }
        else { if(src[j]===c){ j++; break; } }
        val+=src[j]; j++;
      }
      // count newlines in masked
      const raw=src.slice(start,j);
      masked += raw.replace(/[^\n]/g,' ');
      line += (raw.match(/\n/g)||[]).length;
      strings.push({val:val,line:line, raw:raw, delim:delim});
      i=j; continue;
    }
    masked+=c; i++;
  }
  return {masked,strings};
}
