const lfsTxt=String(tools.grep({pattern:'^version https://git-lfs.github.com/spec/v1'}));
const testsTxt=String(tools.glob({pattern:'services/*/tests/test_*.py'}));
const res=[];
for(let k=1;k<=5;k++){const s='svc-'+String(k).padStart(2,'0');const b='services/'+s+'/';
 const cfg=JSON.parse(strip(tools.read({path:b+'config.json'})).join('\n'));
 const dk=strip(tools.read({path:b+'Dockerfile'}));const rd=strip(tools.read({path:b+'README.md'}));
 const co=strip(tools.read({path:b+'CODEOWNERS'}));const rq=strip(tools.read({path:b+'requirements.txt'}));
 const files={};for(const f of ['handlers.py','app.py','util.py','__init__.py'])files[f]=strip(tools.read({path:b+'src/'+f})).join('\n');
 const stored=JSON.parse(strip(tools.read({path:'findings/'+s+'.json'})).join('\n'));
 const isLfs=lfsTxt.split('\n').some(l=>l.indexOf('/services/'+s+'/')>=0);
 let comp;
 if(isLfs){comp={service:s,status:'unverifiable',violations:[]};}
 else{const v=[];
  if(cfg.exposure==='public'&&!(typeof cfg.timeout_s==='number'&&cfg.timeout_s<=30))v.push('C1');
  let nodoc=[];const HL=files['handlers.py'].split('\n');
  for(let i=0;i<HL.length;i++){const m=HL[i].match(/^(\s*)def\s+(handle_\w+)\s*\(/);if(!m)continue;let j=i,depth=0,done=false;while(j<HL.length&&!done){const l2=HL[j];for(let c2=0;c2<l2.length;c2++){const ch=l2[c2];if(ch==='('||ch==='['||ch==='{')depth++;else if(ch===')'||ch===']'||ch==='}')depth--;else if(ch===':'&&depth===0){done=true;break;}}if(!done)j++;}let q=j+1;while(q<HL.length&&HL[q].trim()==='')q++;const body=q<HL.length?HL[q]:'';if(!/^\s*(r|u|f|b)?("""|'''|"|')/.test(body))nodoc.push(m[2]);}
  if(nodoc.length)v.push('C2');
  let pc=0,bs=0;for(const f of ['handlers.py','app.py','util.py','__init__.py']){const a=analyze(files[f]);pc+=barePrints(a.masked);bs+=a.strings.filter(x=>x.val.startsWith('sk_live_')||x.val.startsWith('AKIA')).length;}
  if(pc)v.push('C3');
  if(!(typeof cfg.retries==='number'&&Number.isInteger(cfg.retries)&&cfg.retries>=1&&cfg.retries<=5))v.push('C4');
  let fo=true,fc=0;for(const l of dk){const m=l.trim().match(/^FROM\s+(.*)$/i);if(m){fc++;let r=m[1].trim();if(r.startsWith('--'))r=r.split(/\s+/).slice(1).join(' ');if(!/@sha256:[0-9a-f]{64}$/.test(r.split(/\s+/)[0]))fo=false;}}if(!fo||fc===0)v.push('C5');
  let lu=null;for(const l of dk){const u=l.trim().match(/^USER\s+(.*)$/i);if(u)lu=u[1].trim();}if(lu===null||lu==='root'||lu==='0')v.push('C6');
  if(!rd.some(l=>l==='## Runbook'))v.push('C7');
  let star=null;for(const l of co){const t=l.trim();if(t===''||t.startsWith('#'))continue;const p=t.split(/\s+/);if(p[0]==='*')star=p.slice(1);}if(!(star&&star.indexOf('@team-'+cfg.team)>=0))v.push('C8');
  if(bs)v.push('C9');
  let seg=null;if(cfg.healthcheck){const ps=String(cfg.healthcheck).split('/').filter(Boolean);seg=ps[ps.length-1];}if(!cfg.healthcheck||files['handlers.py'].indexOf('def handle_'+seg+'(')<0)v.push('C10');
  if(cfg.metrics_port===cfg.port)v.push('C11');
  for(const l of rq){const t=l.trim();if(t===''||t.startsWith('#'))continue;if(!/^[A-Za-z0-9_.\-\[\]]+==[^\s=]+(\s+;.*)?$/.test(t)){v.push('C12');break;}}
  if(cfg.log_level==='DEBUG')v.push('C13');
  if(cfg.exposure==='public'&&!(typeof cfg.max_body_kb==='number'&&cfg.max_body_kb<=1024))v.push('C14');
  const hasTest=testsTxt.split('\n').some(p=>p.indexOf('/services/'+s+'/tests/test_')>=0&&p.endsWith('.py'));
  if(!hasTest)v.push('C15');
  if(cfg.exposure==='public'&&!(typeof cfg.rate_limit_rps==='number'&&Number.isInteger(cfg.rate_limit_rps)&&cfg.rate_limit_rps>=1&&cfg.rate_limit_rps<=10000))v.push('C16');
  comp={service:s,status:v.length?'violations':'compliant',violations:v};}
 const same=comp.status===stored.status&&JSON.stringify(comp.violations)===JSON.stringify(stored.violations);
 res.push(s+' '+(same?'OK':'MISMATCH computed='+JSON.stringify(comp)+' stored='+JSON.stringify(stored))+' lfs='+isLfs);}
print(res.join('\n'));

